def missing_seq_number(seqs):
    lo, hi = 0, len(seqs) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if seqs[mid] == seqs[0] + mid:
            lo = mid + 1
        else:
            hi = mid
    return seqs[0] + lo
